package com.nextrade.common.util; import java.security.SecureRandom; public final class RandomIds {private static final SecureRandom R=new SecureRandom();private RandomIds(){} public static String numericCode(int digits){if(digits<4||digits>12)throw new IllegalArgumentException("digits");int min=(int)Math.pow(10,digits-1),max=(int)Math.pow(10,digits)-1;return Integer.toString(min+R.nextInt(max-min+1));}}